describe('Request ID Middleware with trustIncoming', () => {
  function generateWord() {
    return 'HonoIsWebFramework'
  }
  const app = new Hono()
  app.use('/trusted', requestId())
  app.use('/untrusted', requestId({ trustIncoming: false, generator: generateWord }))
  app.use('/explicitTrusted', requestId({ trustIncoming: true, generator: generateWord }))
  app.get('/trusted', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/untrusted', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/explicitTrusted', (c) => c.text(c.get('requestId') ?? 'No Request ID'))

  it('Should use the incoming request id header by default', async () => {
    const res = await app.request('http://localhost/trusted', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('incoming-id')
    expect(await res.text()).toBe('incoming-id')
  })

  it('Should use the incoming request id header when trustIncoming is true', async () => {
    const res = await app.request('http://localhost/explicitTrusted', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('incoming-id')
    expect(await res.text()).toBe('incoming-id')
  })

  it('Should ignore the incoming request id header when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/untrusted', {
      headers: {
        'X-Request-Id': 'incoming-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('HonoIsWebFramework')
    expect(await res.text()).toBe('HonoIsWebFramework')
  })

  it('Should expose the generated id without a request header when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/untrusted')
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('HonoIsWebFramework')
    expect(await res.text()).toBe('HonoIsWebFramework')
  })
})

